import { motion } from "framer-motion";

function Hero() {
  return (
    <section className="hero">
      <div className="container">

        <motion.h1
  initial={{ opacity: 0, y: 40 }}
  animate={{ opacity: 1, y: 0 }}
  transition={{ duration: 0.7 }}
>
  Building Modern <br />
  <span style={{ color: "#8b5cf6" }}>Web Experiences</span>
</motion.h1>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          Frontend developer focused on clean UI & smooth UX
        </motion.p>

        <motion.button whileHover={{ scale: 1.05 }}>
          View Projects
        </motion.button>

      </div>
    </section>
  );
}

export default Hero;
